-- Custom SQL of the ODAG1 Sampling data source in ODAG1_Sampling_Dashboard.twb: one connection, ten related tables.
-- Do not run this file to create anything: Tableau sends these SELECTs itself and nothing is created in Teradata.
-- Kept as a readable copy of the workbook's SQL. Needs Teradata 16.20 or later (TRYCAST).

-- Universe: every current ODAG1 row with its functional area, determination, flags, data checks and what the sample did with it
SELECT d.*, STRTOK(x.Stratum_Path_Txt, '/', 1) AS Engine_Area, CASE WHEN x.Stratum_Path_Txt IS NULL THEN 'Not stratified' WHEN UPPER(STRTOK(x.Stratum_Path_Txt, '/', 1)) = UPPER(d.Functional_Area) THEN 'Agrees' ELSE 'Differs' END AS Area_Check, CASE WHEN d.Determination IN ('Missing', 'Other') THEN 1 ELSE 0 END AS DQ_Missing_Determination, CASE WHEN d.Functional_Area = 'OTHER' THEN 1 ELSE 0 END AS DQ_No_Functional_Area, CASE WHEN d.CPT_List IS NULL THEN 1 ELSE 0 END AS DQ_Missing_CPT, CASE WHEN d.Network = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Provider_Type, CASE WHEN d.Processing = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Processing_Ind, CASE WHEN d.Request_Dt IS NULL THEN 1 ELSE 0 END AS DQ_Bad_Request_Date, CASE WHEN d.Determination_Dt IS NULL AND d.Determination <> 'Missing' THEN 1 ELSE 0 END AS DQ_Bad_Determination_Date, CASE WHEN d.Decision_Days < 0 THEN 1 ELSE 0 END AS DQ_Notice_Before_Request, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_MedNec, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.MBR_WRTN_NOTFTN_DT), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_Written_Notice, CASE WHEN d.Key_Row_Cnt > 1 THEN 1 ELSE 0 END AS DQ_Duplicate_Key, (DQ_Missing_Determination + DQ_No_Functional_Area + DQ_Missing_CPT + DQ_Bad_Provider_Type + DQ_Bad_Processing_Ind + DQ_Bad_Request_Date + DQ_Bad_Determination_Date + DQ_Notice_Before_Request + DQ_Denial_Missing_MedNec + DQ_Denial_Missing_Written_Notice + DQ_Duplicate_Key) AS DQ_Issue_Cnt, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Excluded_Ind = 1 THEN 'Excluded' WHEN x.Selected_Ind = 1 THEN 'Selected' WHEN x.Selection_Stat = 'REPLACED' THEN 'Replaced' WHEN x.Selection_Stat = 'SKIPPED' THEN 'Skipped' ELSE 'Not selected' END AS Sample_Status, x.Smpl_Run_ID, x.Exclusion_Rsn_Txt, x.Not_Selected_Rsn_Txt, x.Stratum_Path_Txt, x.Selection_Order_Nbr, x.Priority_Rank_Nbr, COALESCE(x.Selected_Ind, 0) AS Selected_Ind, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Exclusion_Rsn_Txt = 'SELECTED_IN_LAST_90_DAYS' THEN 'Prior selection' WHEN COALESCE(x.Exclusion_Rsn_Txt, '-') = COALESCE(d.Expected_Exclusion, '-') THEN 'Agrees' ELSE 'Differs' END AS Exclusion_Check FROM (SELECT b.BTCH_ID, b.AUTHZN_ID, b.SRC_DATA_KEY, b.MBR_ID, b.CNTRCT_NUM, b.PBP_NUM, b.FDR_NM, b.AUTHZN_REQ_DT, b.DETRMTN_NOTFTN_DT, b.MBR_WRTN_NOTFTN_DT, b.AUTHZN_REQ_DETRMTN_TY, b.AUTHZN_REQ_STD_OR_EXPDT_IND, b.AUTHZN_REQ_EXPDT_PROCS_STD_IND, b.TIMEFRAME_EXT_IND, b.PART_B_DRUG_REQ_IND, b.REQSTR_TY_CD, b.ISS_DESC, b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, b.SVC_CTGRY_CD, b.AUTHZN_STAT_RSN_DESC, b.AUTHZN_STAT_RSN, b.REQ_PROV_TY, b.SVC_PROV_TY, b.CPT_PROC_CD, b.AUTHZN_REVSN_NUM, b.UNVRS_VRSN_CD, b.FILE_NM, b.Key_Row_Cnt, 'AUTHZN_ID=' || COALESCE(TRIM(TRAILING FROM CAST(b.AUTHZN_ID AS VARCHAR(100))), 'NULL') || '|SRC_DATA_KEY=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(40)))), 'NULL') || '|AUTHZN_REVSN_NUM=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.AUTHZN_REVSN_NUM AS VARCHAR(40)))), 'NULL') AS Case_Key, TRYCAST(SUBSTR(b.BTCH_ID, 1, 4) || '-' || SUBSTR(b.BTCH_ID, 5, 2) || '-' || SUBSTR(b.BTCH_ID, 7, 2) AS DATE) AS Batch_Dt, CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END AS Functional_Area, CASE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END WHEN 'DME' THEN 'OP PAC' WHEN 'HHC' THEN 'OP PAC' WHEN 'OP Medical' THEN 'Medical' WHEN 'IP Medical' THEN 'Medical' ELSE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END END AS Area_Group, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END = 'IP PAC' THEN CASE WHEN UPPER(b.Type_Detail) = 'REHAB' THEN 'IPRF' WHEN UPPER(b.Type_Detail) = 'LTAC' THEN 'LTAC' ELSE 'SNF' END END AS IP_PAC_Type, CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END AS Determination, CASE UPPER(TRIM(b.AUTHZN_REQ_STD_OR_EXPDT_IND)) WHEN 'E' THEN 'Expedited' WHEN 'S' THEN 'Standard' ELSE 'Unknown' END AS Processing, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 'Out of network' WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'PAR' THEN 'In network' ELSE 'Unknown' END AS Network, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 1 ELSE 0 END AS OON_Ind, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' AND UPPER(TRIM(b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND)) = 'Y' THEN 1 ELSE 0 END AS Med_Necessity_Denial_Ind, NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), '') AS CPT_List, TRIM(STRTOK(NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), ''), ',', 1)) AS CPT_First, CASE WHEN COALESCE(TRIM(b.CPT_PROC_CD), '') = '' THEN 0 ELSE CHARACTER_LENGTH(OREPLACE(b.CPT_PROC_CD, ' ', '')) - CHARACTER_LENGTH(OREPLACE(OREPLACE(b.CPT_PROC_CD, ' ', ''), ',', '')) + 1 END AS CPT_Cnt, CASE WHEN b.AUTHZN_REVSN_NUM = 1 THEN 1 ELSE 0 END AS Initial_Auth_Ind, CASE WHEN COALESCE(b.AUTHZN_REVSN_NUM, 0) <> 1 THEN 'REVISION' END AS Expected_Exclusion, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Yes' ELSE 'No' END AS Needs_Clinical_Auditor, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Clinical' ELSE 'Administrative' END AS Auditor_Type, TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Request_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) AS Determination_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) - TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Decision_Days, 1 AS Case_Cnt, b.Request_Type, b.Type_Detail FROM (SELECT o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.MBR_ID, o.CNTRCT_NUM, o.PBP_NUM, o.FDR_NM, o.AUTHZN_REQ_DT, o.DETRMTN_NOTFTN_DT, o.MBR_WRTN_NOTFTN_DT, o.AUTHZN_REQ_DETRMTN_TY, o.AUTHZN_REQ_STD_OR_EXPDT_IND, o.AUTHZN_REQ_EXPDT_PROCS_STD_IND, o.TIMEFRAME_EXT_IND, o.PART_B_DRUG_REQ_IND, o.REQSTR_TY_CD, o.ISS_DESC, o.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, o.SVC_CTGRY_CD, o.AUTHZN_STAT_RSN_DESC, o.AUTHZN_STAT_RSN, o.REQ_PROV_TY, o.SVC_PROV_TY, o.CPT_PROC_CD, o.AUTHZN_REVSN_NUM, o.UNVRS_VRSN_CD, o.FILE_NM, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 1)) AS Request_Type, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 2)) AS Type_Detail, COUNT(*) OVER (PARTITION BY o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.AUTHZN_REVSN_NUM) AS Key_Row_Cnt FROM HSLABBOSS.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 o WHERE UPPER(TRIM(o.ETL_IS_CURR_IND)) = 'Y' AND UPPER(TRIM(o.ETL_IS_DEL_IND)) = 'N' AND UPPER(TRIM(o.RUN_TY)) = 'WKLY') b) d LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SampleSelection x ON UPPER(x.Project_Cd) = 'UMCM' AND UPPER(x.Table_Nm) = 'ODAG1' AND UPPER(x.Run_Ty) = 'WKLY' AND x.Curr_Ind = 1 AND x.Run_Key = d.BTCH_ID AND x.Case_Key = d.Case_Key;

-- Runs: Every run: counts, timing, reruns, overrides, errors, configuration changes
SELECT v.Smpl_Run_ID AS Runs_Smpl_Run_ID, v.Project_Cd, v.Table_Nm, v.Run_Ty, v.Run_Key, v.As_Of_Dt_Key, v.Run_Stat, v.Curr_Ind, v.Random_Seed_Nbr, v.In_Scope_Cnt, v.Excluded_Cnt, v.Candidate_Cnt, v.Selected_Cnt, v.Shortfall_Cnt, v.Target_Cnt, v.Error_Ty, v.Error_Txt, v.Override_Rsn_Txt, v.Rerun_Rsn_Txt, v.Rules_As_Of_Dt, v.Finalized_By, v.Finalized_Dtts, v.Triggered_By, v.Start_Dtts, v.End_Dtts, v.Config_Hash, v.Smpl_Method_Cd, v.Duration_Min, v.Run_Weekday, v.Start_Hour, v.Rerun_Ind, v.Override_Ind, v.Finalized_Ind, v.Failed_Ind, v.Completed_Ind, v.Shortfall_Ind, v.Prior_Config_Hash, v.Run_Version, v.Run_Kind, v.Run_Cnt, v.Config_Changed_Ind, CAST(1 AS INTEGER) AS Model_Link
FROM (
SELECT r.Smpl_Run_ID, r.Project_Cd, r.Table_Nm, r.Run_Ty, r.Run_Key, r.As_Of_Dt_Key, r.Run_Stat, r.Curr_Ind, r.Random_Seed_Nbr, r.In_Scope_Cnt, r.Excluded_Cnt, r.Candidate_Cnt, r.Selected_Cnt, r.Shortfall_Cnt, r.Target_Cnt, r.Error_Ty, r.Error_Txt, r.Override_Rsn_Txt, r.Rerun_Rsn_Txt, r.Rules_As_Of_Dt, r.Finalized_By, r.Finalized_Dtts, r.Triggered_By, r.Start_Dtts, r.End_Dtts, r.Config_Hash, r.Smpl_Method_Cd, CAST(((CAST(r.End_Dtts AS DATE) - DATE '2000-01-01') * 86400 + EXTRACT(HOUR FROM r.End_Dtts) * 3600 + EXTRACT(MINUTE FROM r.End_Dtts) * 60 + EXTRACT(SECOND FROM r.End_Dtts) - (CAST(r.Start_Dtts AS DATE) - DATE '2000-01-01') * 86400 + EXTRACT(HOUR FROM r.Start_Dtts) * 3600 + EXTRACT(MINUTE FROM r.Start_Dtts) * 60 + EXTRACT(SECOND FROM r.Start_Dtts)) / 60.0 AS DECIMAL(12,2)) AS Duration_Min, CASE TD_DAY_OF_WEEK(CAST(r.Start_Dtts AS DATE)) WHEN 1 THEN 'Sun' WHEN 2 THEN 'Mon' WHEN 3 THEN 'Tue' WHEN 4 THEN 'Wed' WHEN 5 THEN 'Thu' WHEN 6 THEN 'Fri' ELSE 'Sat' END AS Run_Weekday, EXTRACT(HOUR FROM r.Start_Dtts) AS Start_Hour, CASE WHEN r.Rerun_Rsn_Txt IS NOT NULL THEN 1 ELSE 0 END AS Rerun_Ind, CASE WHEN r.Override_Rsn_Txt IS NOT NULL THEN 1 ELSE 0 END AS Override_Ind, CASE WHEN r.Run_Stat = 'FINAL' THEN 1 ELSE 0 END AS Finalized_Ind, CASE WHEN r.Run_Stat IN ('ERROR', 'FAILED') THEN 1 ELSE 0 END AS Failed_Ind, CASE WHEN r.Run_Stat IN ('COMPLETED', 'FINAL') THEN 1 ELSE 0 END AS Completed_Ind, CASE WHEN r.Shortfall_Cnt > 0 THEN 1 ELSE 0 END AS Shortfall_Ind, MAX(r.Config_Hash) OVER (PARTITION BY r.Project_Cd, r.Table_Nm, r.Run_Ty ORDER BY r.Start_Dtts ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) AS Prior_Config_Hash, CASE WHEN r.Curr_Ind = 1 THEN 'Current' ELSE 'Replaced by a rerun' END AS Run_Version, CASE WHEN r.Override_Rsn_Txt IS NOT NULL THEN 'Override' WHEN r.Rerun_Rsn_Txt IS NOT NULL THEN 'Rerun' ELSE 'First run' END AS Run_Kind, 1 AS Run_Cnt, CASE WHEN r.Config_Hash <> MAX(r.Config_Hash) OVER (PARTITION BY r.Project_Cd, r.Table_Nm, r.Run_Ty ORDER BY r.Start_Dtts ROWS BETWEEN 1 PRECEDING AND 1 PRECEDING) THEN 1 ELSE 0 END AS Config_Changed_Ind FROM HSLABBOSS.GOVT_RGLTRY_SamplingRun r
) v;

-- Rules: The rules of the UMCM samples, with whether each is in effect today
SELECT v.Rule_ID, v.Project_Cd AS Rules_Project_Cd, v.Table_Nm AS Rules_Table_Nm, v.Run_Ty AS Rules_Run_Ty, v.Rule_Class_Cd, v.Seq_Nbr, v.Rule_Nm, v.Rule_Ty, v.Level_Nbr, v.Parent_Path_Txt, v.Quota_Cd, v.Quota_Val, v.Max_Ty, v.Max_Val, v.Lookback_Days, v.History_Scope_Cd, v.Rule_Desc, v.Active_Ind, v.Eff_Start_Dt, v.Eff_End_Dt, v.Rule_Sql_Txt, v.In_Effect, v.Rule_Cnt
FROM (
SELECT g.Rule_ID, g.Project_Cd, g.Table_Nm, g.Run_Ty, g.Rule_Class_Cd, g.Seq_Nbr, g.Rule_Nm, g.Rule_Ty, g.Level_Nbr, g.Parent_Path_Txt, g.Quota_Cd, g.Quota_Val, g.Max_Ty, g.Max_Val, g.Lookback_Days, g.History_Scope_Cd, g.Rule_Desc, g.Active_Ind, g.Eff_Start_Dt, g.Eff_End_Dt, g.Rule_Sql_Txt, CASE WHEN g.Active_Ind = 1 AND CURRENT_DATE BETWEEN g.Eff_Start_Dt AND g.Eff_End_Dt THEN 'In effect' ELSE 'Not in effect' END AS In_Effect, 1 AS Rule_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRule g WHERE UPPER(g.Project_Cd) IN ('UMCM', '*')
) v;

-- Sample: The current sample of every cycle (the target table) with the case attributes, its status and its stratum weight
SELECT v.BTCH_ID AS Smp_BTCH_ID, v.AUTHZN_ID AS Smp_AUTHZN_ID, v.SRC_DATA_KEY AS Smp_SRC_DATA_KEY, v.MBR_ID AS Smp_MBR_ID, v.CNTRCT_NUM AS Smp_CNTRCT_NUM, v.PBP_NUM AS Smp_PBP_NUM, v.FDR_NM AS Smp_FDR_NM, v.AUTHZN_REQ_DT AS Smp_AUTHZN_REQ_DT, v.DETRMTN_NOTFTN_DT AS Smp_DETRMTN_NOTFTN_DT, v.MBR_WRTN_NOTFTN_DT AS Smp_MBR_WRTN_NOTFTN_DT, v.AUTHZN_REQ_DETRMTN_TY AS Smp_AUTHZN_REQ_DETRMTN_TY, v.AUTHZN_REQ_STD_OR_EXPDT_IND AS Smp_AUTHZN_REQ_STD_OR_EXPDT_IND, v.AUTHZN_REQ_EXPDT_PROCS_STD_IND AS Smp_AUTHZN_REQ_EXPDT_PROCS_STD_IND, v.TIMEFRAME_EXT_IND AS Smp_TIMEFRAME_EXT_IND, v.PART_B_DRUG_REQ_IND AS Smp_PART_B_DRUG_REQ_IND, v.REQSTR_TY_CD AS Smp_REQSTR_TY_CD, v.ISS_DESC AS Smp_ISS_DESC, v.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND AS Smp_REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, v.SVC_CTGRY_CD AS Smp_SVC_CTGRY_CD, v.AUTHZN_STAT_RSN_DESC AS Smp_AUTHZN_STAT_RSN_DESC, v.AUTHZN_STAT_RSN AS Smp_AUTHZN_STAT_RSN, v.REQ_PROV_TY AS Smp_REQ_PROV_TY, v.SVC_PROV_TY AS Smp_SVC_PROV_TY, v.CPT_PROC_CD AS Smp_CPT_PROC_CD, v.AUTHZN_REVSN_NUM AS Smp_AUTHZN_REVSN_NUM, v.UNVRS_VRSN_CD AS Smp_UNVRS_VRSN_CD, v.FILE_NM AS Smp_FILE_NM, v.SMPL_RUN_ID AS Smp_SMPL_RUN_ID, v.SMPL_RUN_KEY, v.SMPL_CYCLE_DT, v.SMPL_ORDER_NBR, v.SMPL_STRATUM_PATH, v.Case_Key AS Smp_Case_Key, v.Batch_Dt AS Smp_Batch_Dt, v.Functional_Area AS Smp_Functional_Area, v.Area_Group AS Smp_Area_Group, v.IP_PAC_Type AS Smp_IP_PAC_Type, v.Determination AS Smp_Determination, v.Processing AS Smp_Processing, v.Network AS Smp_Network, v.OON_Ind AS Smp_OON_Ind, v.Med_Necessity_Denial_Ind AS Smp_Med_Necessity_Denial_Ind, v.CPT_List AS Smp_CPT_List, v.CPT_First AS Smp_CPT_First, v.CPT_Cnt AS Smp_CPT_Cnt, v.Initial_Auth_Ind AS Smp_Initial_Auth_Ind, v.Expected_Exclusion AS Smp_Expected_Exclusion, v.Needs_Clinical_Auditor AS Smp_Needs_Clinical_Auditor, v.Auditor_Type AS Smp_Auditor_Type, v.Request_Dt AS Smp_Request_Dt, v.Determination_Dt AS Smp_Determination_Dt, v.Decision_Days AS Smp_Decision_Days, v.Case_Cnt AS Smp_Case_Cnt, v.Request_Type AS Smp_Request_Type, v.Type_Detail AS Smp_Type_Detail, v.Run_Stat AS Smp_Run_Stat, v.Finalized_By AS Smp_Finalized_By, v.Finalized_Dtts AS Smp_Finalized_Dtts, v.Run_End_Dtts, v.Selection_Stat, v.Linked_Case_Key, v.Stat_Rsn_Txt, v.Stat_By, v.Priority_Rank_Nbr AS Smp_Priority_Rank_Nbr, v.Bucket_Rank_Nbr, v.Stratum_Candidate_Cnt, v.Stratum_Selected_Cnt, v.Design_Weight, v.Sampling_Fraction
FROM (
SELECT b.BTCH_ID, b.AUTHZN_ID, b.SRC_DATA_KEY, b.MBR_ID, b.CNTRCT_NUM, b.PBP_NUM, b.FDR_NM, b.AUTHZN_REQ_DT, b.DETRMTN_NOTFTN_DT, b.MBR_WRTN_NOTFTN_DT, b.AUTHZN_REQ_DETRMTN_TY, b.AUTHZN_REQ_STD_OR_EXPDT_IND, b.AUTHZN_REQ_EXPDT_PROCS_STD_IND, b.TIMEFRAME_EXT_IND, b.PART_B_DRUG_REQ_IND, b.REQSTR_TY_CD, b.ISS_DESC, b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, b.SVC_CTGRY_CD, b.AUTHZN_STAT_RSN_DESC, b.AUTHZN_STAT_RSN, b.REQ_PROV_TY, b.SVC_PROV_TY, b.CPT_PROC_CD, b.AUTHZN_REVSN_NUM, b.UNVRS_VRSN_CD, b.FILE_NM, b.SMPL_RUN_ID, b.SMPL_RUN_KEY, b.SMPL_CYCLE_DT, b.SMPL_ORDER_NBR, b.SMPL_STRATUM_PATH, 'AUTHZN_ID=' || COALESCE(TRIM(TRAILING FROM CAST(b.AUTHZN_ID AS VARCHAR(100))), 'NULL') || '|SRC_DATA_KEY=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(40)))), 'NULL') || '|AUTHZN_REVSN_NUM=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.AUTHZN_REVSN_NUM AS VARCHAR(40)))), 'NULL') AS Case_Key, TRYCAST(SUBSTR(b.BTCH_ID, 1, 4) || '-' || SUBSTR(b.BTCH_ID, 5, 2) || '-' || SUBSTR(b.BTCH_ID, 7, 2) AS DATE) AS Batch_Dt, CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END AS Functional_Area, CASE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END WHEN 'DME' THEN 'OP PAC' WHEN 'HHC' THEN 'OP PAC' WHEN 'OP Medical' THEN 'Medical' WHEN 'IP Medical' THEN 'Medical' ELSE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END END AS Area_Group, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END = 'IP PAC' THEN CASE WHEN UPPER(b.Type_Detail) = 'REHAB' THEN 'IPRF' WHEN UPPER(b.Type_Detail) = 'LTAC' THEN 'LTAC' ELSE 'SNF' END END AS IP_PAC_Type, CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END AS Determination, CASE UPPER(TRIM(b.AUTHZN_REQ_STD_OR_EXPDT_IND)) WHEN 'E' THEN 'Expedited' WHEN 'S' THEN 'Standard' ELSE 'Unknown' END AS Processing, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 'Out of network' WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'PAR' THEN 'In network' ELSE 'Unknown' END AS Network, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 1 ELSE 0 END AS OON_Ind, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' AND UPPER(TRIM(b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND)) = 'Y' THEN 1 ELSE 0 END AS Med_Necessity_Denial_Ind, NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), '') AS CPT_List, TRIM(STRTOK(NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), ''), ',', 1)) AS CPT_First, CASE WHEN COALESCE(TRIM(b.CPT_PROC_CD), '') = '' THEN 0 ELSE CHARACTER_LENGTH(OREPLACE(b.CPT_PROC_CD, ' ', '')) - CHARACTER_LENGTH(OREPLACE(OREPLACE(b.CPT_PROC_CD, ' ', ''), ',', '')) + 1 END AS CPT_Cnt, CASE WHEN b.AUTHZN_REVSN_NUM = 1 THEN 1 ELSE 0 END AS Initial_Auth_Ind, CASE WHEN COALESCE(b.AUTHZN_REVSN_NUM, 0) <> 1 THEN 'REVISION' END AS Expected_Exclusion, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Yes' ELSE 'No' END AS Needs_Clinical_Auditor, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Clinical' ELSE 'Administrative' END AS Auditor_Type, TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Request_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) AS Determination_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) - TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Decision_Days, 1 AS Case_Cnt, b.Request_Type, b.Type_Detail, r.Run_Stat, r.Finalized_By, r.Finalized_Dtts, r.End_Dtts AS Run_End_Dtts, COALESCE(x.Selection_Stat, 'SELECTED') AS Selection_Stat, x.Linked_Case_Key, x.Stat_Rsn_Txt, x.Stat_By, x.Priority_Rank_Nbr, x.Bucket_Rank_Nbr, t.Candidate_Cnt AS Stratum_Candidate_Cnt, t.Selected_Cnt AS Stratum_Selected_Cnt, CASE WHEN t.Selected_Cnt > 0 THEN CAST(t.Candidate_Cnt AS DECIMAL(18,4)) / t.Selected_Cnt END AS Design_Weight, CASE WHEN t.Candidate_Cnt > 0 THEN CAST(t.Selected_Cnt AS DECIMAL(18,4)) / t.Candidate_Cnt END AS Sampling_Fraction FROM (SELECT o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.MBR_ID, o.CNTRCT_NUM, o.PBP_NUM, o.FDR_NM, o.AUTHZN_REQ_DT, o.DETRMTN_NOTFTN_DT, o.MBR_WRTN_NOTFTN_DT, o.AUTHZN_REQ_DETRMTN_TY, o.AUTHZN_REQ_STD_OR_EXPDT_IND, o.AUTHZN_REQ_EXPDT_PROCS_STD_IND, o.TIMEFRAME_EXT_IND, o.PART_B_DRUG_REQ_IND, o.REQSTR_TY_CD, o.ISS_DESC, o.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, o.SVC_CTGRY_CD, o.AUTHZN_STAT_RSN_DESC, o.AUTHZN_STAT_RSN, o.REQ_PROV_TY, o.SVC_PROV_TY, o.CPT_PROC_CD, o.AUTHZN_REVSN_NUM, o.UNVRS_VRSN_CD, o.FILE_NM, o.SMPL_RUN_ID, o.SMPL_RUN_KEY, o.SMPL_CYCLE_DT, o.SMPL_ORDER_NBR, o.SMPL_STRATUM_PATH, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 1)) AS Request_Type, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 2)) AS Type_Detail, COUNT(*) OVER (PARTITION BY o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.AUTHZN_REVSN_NUM) AS Key_Row_Cnt FROM HSLABBOSS.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1_Sample o WHERE UPPER(TRIM(o.ETL_IS_CURR_IND)) = 'Y') b JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRun r ON r.Smpl_Run_ID = b.SMPL_RUN_ID AND r.Curr_Ind = 1 LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SampleSelection x ON x.Smpl_Run_ID = b.SMPL_RUN_ID AND x.Case_Key = 'AUTHZN_ID=' || COALESCE(TRIM(TRAILING FROM CAST(b.AUTHZN_ID AS VARCHAR(100))), 'NULL') || '|SRC_DATA_KEY=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(40)))), 'NULL') || '|AUTHZN_REVSN_NUM=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.AUTHZN_REVSN_NUM AS VARCHAR(40)))), 'NULL') LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRunStat t ON t.Smpl_Run_ID = b.SMPL_RUN_ID AND t.Stat_Ty = 'BUCKET' AND t.Stat_Nm = b.SMPL_STRATUM_PATH
) v;

-- Run figures: The figures of every completed run: buckets, caps, exclusions, rules
SELECT v.Smpl_Run_ID AS Stat_Smpl_Run_ID, v.Project_Cd AS Stat_Project_Cd, v.Table_Nm AS Stat_Table_Nm, v.Run_Ty AS Stat_Run_Ty, v.Run_Key AS Stat_Run_Key, v.As_Of_Dt_Key AS Stat_As_Of_Dt_Key, v.Stat_Ty, v.Stat_Seq_Nbr, v.Stat_Nm, v.Rule_ID AS Stat_Rule_ID, v.Leaf_Ind, v.Candidate_Cnt AS Stat_Candidate_Cnt, v.Target_Cnt AS Stat_Target_Cnt, v.Selected_Cnt AS Stat_Selected_Cnt, v.Limit_Cnt, v.Over_Cnt, v.Replaced_Cnt, v.Case_Cnt AS Stat_Case_Cnt, v.Stat_Txt, v.Run_Curr_Ind, v.Run_Stat AS Stat_Run_Stat, v.Run_Start_Dtts, v.Path_Depth, v.Path_Level_1, v.Path_Level_2, v.Path_Level_3, v.Bucket_Shortfall_Cnt, v.Sampling_Fraction AS Stat_Sampling_Fraction, v.Stat_Kind, v.Leaf_Target_Cnt, v.Leaf_Selected_Cnt, v.Leaf_Candidate_Cnt
FROM (
SELECT t.Smpl_Run_ID, t.Project_Cd, t.Table_Nm, t.Run_Ty, t.Run_Key, t.As_Of_Dt_Key, t.Stat_Ty, t.Stat_Seq_Nbr, t.Stat_Nm, t.Rule_ID, t.Leaf_Ind, t.Candidate_Cnt, t.Target_Cnt, t.Selected_Cnt, t.Limit_Cnt, t.Over_Cnt, t.Replaced_Cnt, t.Case_Cnt, t.Stat_Txt, r.Curr_Ind AS Run_Curr_Ind, r.Run_Stat AS Run_Stat, r.Start_Dtts AS Run_Start_Dtts, CASE WHEN t.Stat_Ty = 'BUCKET' THEN CHARACTER_LENGTH(t.Stat_Nm) - CHARACTER_LENGTH(OREPLACE(t.Stat_Nm, '/', '')) + 1 END AS Path_Depth, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 1) END AS Path_Level_1, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 2) END AS Path_Level_2, CASE WHEN t.Stat_Ty = 'BUCKET' THEN STRTOK(t.Stat_Nm, '/', 3) END AS Path_Level_3, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Target_Cnt > t.Selected_Cnt THEN t.Target_Cnt - t.Selected_Cnt ELSE 0 END AS Bucket_Shortfall_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Candidate_Cnt > 0 THEN CAST(t.Selected_Cnt AS DECIMAL(18,4)) / t.Candidate_Cnt END AS Sampling_Fraction, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN 'Leaf bucket' WHEN t.Stat_Ty = 'BUCKET' THEN 'Parent bucket' ELSE t.Stat_Ty END AS Stat_Kind, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Target_Cnt ELSE 0 END AS Leaf_Target_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Selected_Cnt ELSE 0 END AS Leaf_Selected_Cnt, CASE WHEN t.Stat_Ty = 'BUCKET' AND t.Leaf_Ind = 1 THEN t.Candidate_Cnt ELSE 0 END AS Leaf_Candidate_Cnt FROM HSLABBOSS.GOVT_RGLTRY_SamplingRunStat t JOIN HSLABBOSS.GOVT_RGLTRY_SamplingRun r ON r.Smpl_Run_ID = t.Smpl_Run_ID AND r.Curr_Ind = 1
) v;

-- Universe risks and errors: one row per data check a row fails
SELECT v.BTCH_ID AS DQ_BTCH_ID, v.Batch_Dt AS DQ_Batch_Dt, v.AUTHZN_ID AS DQ_AUTHZN_ID, v.SRC_DATA_KEY AS DQ_SRC_DATA_KEY, v.Case_Key AS DQ_Case_Key, v.Functional_Area AS DQ_Functional_Area, v.Determination AS DQ_Determination, v.Processing AS DQ_Processing, v.Sample_Status AS DQ_Sample_Status, v.Issue_Txt, v.Severity_Txt, v.Column_Nm, v.Value_Txt, v.Issue_Cnt
FROM (
SELECT u.BTCH_ID, u.Batch_Dt, u.AUTHZN_ID, u.SRC_DATA_KEY, u.Case_Key, u.Functional_Area, u.Determination, u.Processing, u.Sample_Status, 'Determination missing or not a known value' AS Issue_Txt, 'Error' AS Severity_Txt, 'AUTHZN_REQ_DETRMTN_TY' AS Column_Nm, CAST(u.AUTHZN_REQ_DETRMTN_TY AS VARCHAR(500)) AS Value_Txt, 1 AS Issue_Cnt FROM (
SELECT d.*, STRTOK(x.Stratum_Path_Txt, '/', 1) AS Engine_Area, CASE WHEN x.Stratum_Path_Txt IS NULL THEN 'Not stratified' WHEN UPPER(STRTOK(x.Stratum_Path_Txt, '/', 1)) = UPPER(d.Functional_Area) THEN 'Agrees' ELSE 'Differs' END AS Area_Check, CASE WHEN d.Determination IN ('Missing', 'Other') THEN 1 ELSE 0 END AS DQ_Missing_Determination, CASE WHEN d.Functional_Area = 'OTHER' THEN 1 ELSE 0 END AS DQ_No_Functional_Area, CASE WHEN d.CPT_List IS NULL THEN 1 ELSE 0 END AS DQ_Missing_CPT, CASE WHEN d.Network = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Provider_Type, CASE WHEN d.Processing = 'Unknown' THEN 1 ELSE 0 END AS DQ_Bad_Processing_Ind, CASE WHEN d.Request_Dt IS NULL THEN 1 ELSE 0 END AS DQ_Bad_Request_Date, CASE WHEN d.Determination_Dt IS NULL AND d.Determination <> 'Missing' THEN 1 ELSE 0 END AS DQ_Bad_Determination_Date, CASE WHEN d.Decision_Days < 0 THEN 1 ELSE 0 END AS DQ_Notice_Before_Request, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_MedNec, CASE WHEN d.Determination = 'Denied' AND COALESCE(TRIM(d.MBR_WRTN_NOTFTN_DT), '') = '' THEN 1 ELSE 0 END AS DQ_Denial_Missing_Written_Notice, CASE WHEN d.Key_Row_Cnt > 1 THEN 1 ELSE 0 END AS DQ_Duplicate_Key, (DQ_Missing_Determination + DQ_No_Functional_Area + DQ_Missing_CPT + DQ_Bad_Provider_Type + DQ_Bad_Processing_Ind + DQ_Bad_Request_Date + DQ_Bad_Determination_Date + DQ_Notice_Before_Request + DQ_Denial_Missing_MedNec + DQ_Denial_Missing_Written_Notice + DQ_Duplicate_Key) AS DQ_Issue_Cnt, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Excluded_Ind = 1 THEN 'Excluded' WHEN x.Selected_Ind = 1 THEN 'Selected' WHEN x.Selection_Stat = 'REPLACED' THEN 'Replaced' WHEN x.Selection_Stat = 'SKIPPED' THEN 'Skipped' ELSE 'Not selected' END AS Sample_Status, x.Smpl_Run_ID, x.Exclusion_Rsn_Txt, x.Not_Selected_Rsn_Txt, x.Stratum_Path_Txt, x.Selection_Order_Nbr, x.Priority_Rank_Nbr, COALESCE(x.Selected_Ind, 0) AS Selected_Ind, CASE WHEN x.Case_Key IS NULL THEN 'Not sampled' WHEN x.Exclusion_Rsn_Txt = 'SELECTED_IN_LAST_90_DAYS' THEN 'Prior selection' WHEN COALESCE(x.Exclusion_Rsn_Txt, '-') = COALESCE(d.Expected_Exclusion, '-') THEN 'Agrees' ELSE 'Differs' END AS Exclusion_Check FROM (SELECT b.BTCH_ID, b.AUTHZN_ID, b.SRC_DATA_KEY, b.MBR_ID, b.CNTRCT_NUM, b.PBP_NUM, b.FDR_NM, b.AUTHZN_REQ_DT, b.DETRMTN_NOTFTN_DT, b.MBR_WRTN_NOTFTN_DT, b.AUTHZN_REQ_DETRMTN_TY, b.AUTHZN_REQ_STD_OR_EXPDT_IND, b.AUTHZN_REQ_EXPDT_PROCS_STD_IND, b.TIMEFRAME_EXT_IND, b.PART_B_DRUG_REQ_IND, b.REQSTR_TY_CD, b.ISS_DESC, b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, b.SVC_CTGRY_CD, b.AUTHZN_STAT_RSN_DESC, b.AUTHZN_STAT_RSN, b.REQ_PROV_TY, b.SVC_PROV_TY, b.CPT_PROC_CD, b.AUTHZN_REVSN_NUM, b.UNVRS_VRSN_CD, b.FILE_NM, b.Key_Row_Cnt, 'AUTHZN_ID=' || COALESCE(TRIM(TRAILING FROM CAST(b.AUTHZN_ID AS VARCHAR(100))), 'NULL') || '|SRC_DATA_KEY=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.SRC_DATA_KEY AS VARCHAR(40)))), 'NULL') || '|AUTHZN_REVSN_NUM=' || COALESCE(TRIM(TRAILING '.' FROM TRIM(CAST(b.AUTHZN_REVSN_NUM AS VARCHAR(40)))), 'NULL') AS Case_Key, TRYCAST(SUBSTR(b.BTCH_ID, 1, 4) || '-' || SUBSTR(b.BTCH_ID, 5, 2) || '-' || SUBSTR(b.BTCH_ID, 7, 2) AS DATE) AS Batch_Dt, CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END AS Functional_Area, CASE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END WHEN 'DME' THEN 'OP PAC' WHEN 'HHC' THEN 'OP PAC' WHEN 'OP Medical' THEN 'Medical' WHEN 'IP Medical' THEN 'Medical' ELSE CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END END AS Area_Group, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_STAT_RSN)) = 'CONCURRENT REVIEW' THEN 'Concurrent Review' WHEN UPPER(b.Request_Type) = 'DRUGS - BIOLOGICS PART B' THEN 'Part B' WHEN UPPER(b.Request_Type) LIKE 'BEHAVIORAL HEALTH%' OR (UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'BEHAVIORAL HEALTH') THEN 'BH' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) LIKE 'DURABLE MEDICAL EQUIPMENT%' THEN 'DME' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' AND UPPER(b.Type_Detail) = 'HOME HEALTH SERVICES' THEN 'HHC' WHEN UPPER(b.Request_Type) = 'INPATIENT' AND (UPPER(b.Type_Detail) IN ('REHAB', 'LTAC') OR UPPER(b.Type_Detail) LIKE 'SNF%') THEN 'IP PAC' WHEN UPPER(b.Request_Type) = 'OUTPATIENT' THEN 'OP Medical' WHEN UPPER(b.Request_Type) = 'INPATIENT' THEN 'IP Medical' ELSE 'OTHER' END = 'IP PAC' THEN CASE WHEN UPPER(b.Type_Detail) = 'REHAB' THEN 'IPRF' WHEN UPPER(b.Type_Detail) = 'LTAC' THEN 'LTAC' ELSE 'SNF' END END AS IP_PAC_Type, CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END AS Determination, CASE UPPER(TRIM(b.AUTHZN_REQ_STD_OR_EXPDT_IND)) WHEN 'E' THEN 'Expedited' WHEN 'S' THEN 'Standard' ELSE 'Unknown' END AS Processing, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 'Out of network' WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'PAR' THEN 'In network' ELSE 'Unknown' END AS Network, CASE WHEN UPPER(TRIM(b.SVC_PROV_TY)) = 'NON PAR' THEN 1 ELSE 0 END AS OON_Ind, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' AND UPPER(TRIM(b.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND)) = 'Y' THEN 1 ELSE 0 END AS Med_Necessity_Denial_Ind, NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), '') AS CPT_List, TRIM(STRTOK(NULLIF(OREPLACE(COALESCE(b.CPT_PROC_CD, ''), ' ', ''), ''), ',', 1)) AS CPT_First, CASE WHEN COALESCE(TRIM(b.CPT_PROC_CD), '') = '' THEN 0 ELSE CHARACTER_LENGTH(OREPLACE(b.CPT_PROC_CD, ' ', '')) - CHARACTER_LENGTH(OREPLACE(OREPLACE(b.CPT_PROC_CD, ' ', ''), ',', '')) + 1 END AS CPT_Cnt, CASE WHEN b.AUTHZN_REVSN_NUM = 1 THEN 1 ELSE 0 END AS Initial_Auth_Ind, CASE WHEN COALESCE(b.AUTHZN_REVSN_NUM, 0) <> 1 THEN 'REVISION' END AS Expected_Exclusion, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Yes' ELSE 'No' END AS Needs_Clinical_Auditor, CASE WHEN CASE WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'APPROVED' THEN 'Approved' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DENIED' THEN 'Denied' WHEN UPPER(TRIM(b.AUTHZN_REQ_DETRMTN_TY)) = 'DISMISSED' THEN 'Dismissed' WHEN COALESCE(TRIM(b.AUTHZN_REQ_DETRMTN_TY), '') = '' THEN 'Missing' ELSE 'Other' END = 'Denied' THEN 'Clinical' ELSE 'Administrative' END AS Auditor_Type, TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Request_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) AS Determination_Dt, TRYCAST(OREPLACE(TRIM(b.DETRMTN_NOTFTN_DT), '/', '-') AS DATE) - TRYCAST(OREPLACE(TRIM(b.AUTHZN_REQ_DT), '/', '-') AS DATE) AS Decision_Days, 1 AS Case_Cnt, b.Request_Type, b.Type_Detail FROM (SELECT o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.MBR_ID, o.CNTRCT_NUM, o.PBP_NUM, o.FDR_NM, o.AUTHZN_REQ_DT, o.DETRMTN_NOTFTN_DT, o.MBR_WRTN_NOTFTN_DT, o.AUTHZN_REQ_DETRMTN_TY, o.AUTHZN_REQ_STD_OR_EXPDT_IND, o.AUTHZN_REQ_EXPDT_PROCS_STD_IND, o.TIMEFRAME_EXT_IND, o.PART_B_DRUG_REQ_IND, o.REQSTR_TY_CD, o.ISS_DESC, o.REQ_DENY_FOR_LACK_OF_MED_NECTY_IND, o.SVC_CTGRY_CD, o.AUTHZN_STAT_RSN_DESC, o.AUTHZN_STAT_RSN, o.REQ_PROV_TY, o.SVC_PROV_TY, o.CPT_PROC_CD, o.AUTHZN_REVSN_NUM, o.UNVRS_VRSN_CD, o.FILE_NM, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 1)) AS Request_Type, TRIM(STRTOK(NULLIF(TRIM(o.ISS_DESC), ''), ',', 2)) AS Type_Detail, COUNT(*) OVER (PARTITION BY o.BTCH_ID, o.AUTHZN_ID, o.SRC_DATA_KEY, o.AUTHZN_REVSN_NUM) AS Key_Row_Cnt FROM HSLABBOSS.SDO_GOVT_RGLTRY_CLNCL_AUD_UM_AUTHZN_ODAG1 o WHERE UPPER(TRIM(o.ETL_IS_CURR_IND)) = 'Y' AND UPPER(TRIM(o.ETL_IS_DEL_IND)) = 'N' AND UPPER(TRIM(o.RUN_TY)) = 'WKLY') b) d LEFT JOIN HSLABBOSS.GOVT_RGLTRY_SampleSelection x ON UPPER(x.Project_Cd) = 'UMCM' AND UPPER(x.Table_Nm) = 'ODAG1' AND UPPER(x.Run_Ty) = 'WKLY' AND x.Curr_Ind = 1 AND x.Run_Key = d.BTCH_ID AND x.Case_Key = d.Case_Key
) u WHERE u.DQ_Missing_Determination = 1
UNION ALL
